from hypothesis import strategies as st

CHARS = "()x"


def _reachable(a, b):
    # Operations (xx) <-> xx are mutually inverse, so reachability is symmetric.
    # BFS from a, with intermediate length capped at max(|a|,|b|)+4.
    cap = max(len(a), len(b)) + 4
    seen = {a}
    stack = [a]
    while stack:
        s = stack.pop()
        if s == b:
            return True
        for i in range(len(s)):
            # (xx) -> xx
            if s[i:i + 4] == "(xx)":
                t = s[:i] + "xx" + s[i + 4:]
                if t not in seen:
                    seen.add(t)
                    stack.append(t)
            # xx -> (xx)
            if s[i:i + 2] == "xx" and len(s) + 2 <= cap:
                t = s[:i] + "(xx)" + s[i + 2:]
                if t not in seen:
                    seen.add(t)
                    stack.append(t)
    return False


@st.composite
def _walk(draw, a):
    s = a
    steps = draw(st.integers(0, 4))
    for _ in range(steps):
        opts = []
        for i in range(len(s)):
            if s[i:i + 4] == "(xx)":
                opts.append(s[:i] + "xx" + s[i + 4:])
            if s[i:i + 2] == "xx":
                opts.append(s[:i] + "(xx)" + s[i + 2:])
        opts = [o for o in opts if len(o) <= 5]
        if not opts:
            break
        idx = draw(st.integers(0, len(opts) - 1))
        s = opts[idx]
    return s


