ALPHA = "()x"


def _reach(a, M):
    # All strings reachable from a using both operations, keeping length <= M.
    # Both operations are applied in their forward direction only; since they
    # are mutual inverses, every reachable string is covered.
    seen = {a}
    q = [a]
    for s in q:
        n = len(s)
        for i in range(n):
            if s.startswith("(xx)", i):
                t = s[:i] + "xx" + s[i + 4:]
                if t not in seen:
                    seen.add(t)
                    q.append(t)
            if s.startswith("xx", i) and n + 2 <= M:
                t = s[:i] + "(xx)" + s[i + 2:]
                if t not in seen:
                    seen.add(t)
                    q.append(t)
    return seen


